local ServiceCollection = require(script.Parent.ServiceCollection)
local ServiceDescriptor = require(script.Parent.ServiceDescriptor)
local ServiceLifetime = require(script.Parent.ServiceLifetime)
local IsServiceChecker = require(script.Parent.IsServiceChecker)
local ServiceMaker = require(script.Parent.ServiceMaker)
local ServiceProvider = require(script.Parent.ServiceProvider)

local ServiceProviderCreator = {}
ServiceProviderCreator.__index = ServiceProviderCreator

function ServiceProviderCreator.new(servicesOrLuaTypeProvider: ServiceCollection.Type, luaTypeProvider)
	local services = nil
	if luaTypeProvider == nil then
		luaTypeProvider = servicesOrLuaTypeProvider
	else
		services = servicesOrLuaTypeProvider
	end

	assert(luaTypeProvider, "luaTypeProvider is required")

	assert(luaTypeProvider.IsLuaTypeProvider, "luaTypeProvider must be a LuaTypeProvider")

	local self = setmetatable({}, ServiceProviderCreator)
	self.Services = ServiceCollection.new()
	self._luaTypeProvider = luaTypeProvider
	self._serviceMakers = {}
	self._serviceMakerLists = {}

	self:Register(ServiceDescriptor.newWithFactory("ServiceProvider", function(_) end, ServiceLifetime.Singleton))
	self:Register(ServiceDescriptor.newWithFactory("ServiceScopeFactory", function(x)
		error("not impl")
	end, ServiceLifetime.Singleton))
	local checker = IsServiceChecker.new(self.Services)
	self:Register(ServiceDescriptor.new("ServiceProviderIsService", checker))

	if services and services._descriptors then
		for _, serviceDescriptor in ipairs(services._descriptors) do
			self:Register(serviceDescriptor)
		end
	end

	return self
end

function ServiceProviderCreator:ServiceCount()
	return self.Services:Count()
end

function ServiceProviderCreator:Register(descriptor)
	self.Services:Add(descriptor)
end

function ServiceProviderCreator:Build()
	for _, descriptor in ipairs(self.Services) do
		self:_validateDescrptor(descriptor)
		local sm = ServiceMaker.new(descriptor)
		self:_updateMakers(descriptor.ServiceType, sm)
	end

	local serviceProvider = ServiceProvider.new(nil, self.Services, self._luaTypeProvider)
	return serviceProvider
end

function ServiceProviderCreator:_validateDescrptor(descriptor)
	local serviceType = descriptor.ServiceType
	local implementationType = descriptor.ImplementationType
	if implementationType == nil then
		return
	end

	local isPass = true
	local errMessage = string.format(
		"Cannot instantiate implementation type '%s' for service type '%s'.",
		implementationType,
		serviceType
	)

	if implementationType.IsAbstract then
		isPass = false
	end

	if implementationType.IsGenericTypeDefinition then
		if serviceType.IsGenericTypeDefinition then
			if
				#implementationType:GetGenericTypeDefinition():GetGenericArguments()
				~= #serviceType:GetGenericArguments()
			then
				errMessage = string.format(
					"Arity of open generic service type '%s' does not equal arity of open generic implementation type '%s'.",
					serviceType,
					implementationType
				)
				isPass = false
			end
		else
			isPass = false
		end
	else
		if serviceType.IsGenericTypeDefinition then
			isPass = false
			errMessage = string.format(
				"Open generic service type '%s' requires registering an open generic implementation type.",
				serviceType
			)
		end
	end

	if not isPass then
		error(errMessage)
	end
end

function ServiceProviderCreator:_updateMakers(interface, sm)
	self._serviceMakers[interface] = sm

	if not typeof("IEnumerable").IsAssignableFrom(interface) then
		if not self._serviceMakerLists[interface] then
			self._serviceMakerLists[interface] = {}
		end
		table.insert(self._serviceMakerLists[interface], 1, sm)
	end
end

return ServiceProviderCreator
